def resolve(path, cwd, links):
    if links is None:
        links = {}

    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    components = path.split('/')
    link_count = 0

    i = 0
    while i < len(components):
        component = components[i]

        if component == '' or component == '.':
            i += 1
            continue

        if component == '..':
            if current == '':
                current = ''
            else:
                last_slash = current.rfind('/')
                if last_slash == -1:
                    current = ''
                else:
                    current = current[:last_slash]
            i += 1
            continue

        if current == '':
            current = '/' + component
        else:
            current = current + '/' + component

        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]
            remaining_components = components[i+1:]

            if target.startswith('/'):
                current = ''
                target_components = target.split('/')
            else:
                last_slash = current.rfind('/')
                if last_slash == -1:
                    current = ''
                else:
                    current = current[:last_slash]
                target_components = target.split('/')

            components = target_components + remaining_components
            i = 0
            continue

        i += 1

    if current == '':
        return '/'
    return current

